-- WildDrops
-- Shows whether a mob can drop an item that starts a quest you can still do.
-- Data: Data.lua (generated by tools/generate.py from QuestieDB)
--
-- Core: settings, quest availability, formatting, refresh and events. The other files
-- are modules that share this through the addon namespace (ns) and hook in with
-- ns.OnLogin, ns.OnRefresh and ns.RegisterEvent.

local ADDON_NAME, addonNS = ...
local ns = addonNS.WildDropsCore or {}
addonNS.WildDropsCore = ns

ns.PREFIX = "|cffffd100WildDrops:|r "
ns.RARE_CHANCE = 0.1 -- drops below this percentage are hidden unless showRare is on
local QUEST_ICON = "Interface\\GossipFrame\\AvailableQuestIcon"

ns.defaults = {
    enabled = true,
    tooltip = true,
    showRare = true, -- include low-probability drops by default
}

-- ns.db is the saved settings table, available from ADDON_LOADED on.
local questsInLog = {}
ns.questsInLog = questsInLog
local playerRace, playerClass, playerLevel
local statusCache = {}    -- [drop entry] = status string, or false when hidden
local availableCache = {} -- [npcID] = GetAvailableDrops result, or false when none

-------------------------------------------------------------------------------
-- Helpers
-------------------------------------------------------------------------------

ns.IsQuestCompleted = (C_QuestLog and C_QuestLog.IsQuestFlaggedCompleted) or IsQuestFlaggedCompleted
ns.GetItemInfo = (C_Item and C_Item.GetItemInfo) or GetItemInfo
ns.GetItemCount = (C_Item and C_Item.GetItemCount) or GetItemCount
local IsQuestCompleted, GetItemInfo, GetItemCount = ns.IsQuestCompleted, ns.GetItemInfo, ns.GetItemCount

-- Newer clients hide some values from addons ("secret values", e.g. the GUID of the
-- unit under the cursor in some situations). They may be passed around but not read:
-- strsplit, tostring or comparisons on them throw an error.
local issecretvalue = issecretvalue -- nil on clients without secret values
function ns.IsSecret(value)
    return issecretvalue ~= nil and issecretvalue(value) == true
end

-- NPC ID from a unit GUID, or nil (players, objects, or a GUID we may not read).
function ns.GetNpcID(guid)
    if not guid or ns.IsSecret(guid) then return end
    local unitType, _, _, _, _, npcID = strsplit("-", guid)
    if unitType == "Creature" or unitType == "Vehicle" then
        return tonumber(npcID)
    end
end

-- QuestieDB requiredRaces bit per race ID. Not simply 2^(raceID-1): Forever's
-- Skyborne races (95/96) use bits 32/33.
local RACE_MASK = {
    [1] = 1, [2] = 2, [3] = 4, [4] = 8, [5] = 16, [6] = 32, [7] = 64, [8] = 128,
    [9] = 256, [10] = 512, [11] = 1024, [22] = 2097152,
    [24] = 8388608, [25] = 16777216, [26] = 33554432,
    [95] = 4294967296, [96] = 8589934592,
}

-- Tests one bit with plain arithmetic: the client's bit library is 32-bit only.
local function MaskHas(mask, bitValue)
    if not mask or mask == 0 or not bitValue then return true end
    return floor(mask / bitValue) % 2 == 1
end

local function RaceAllowed(mask, raceID)
    return MaskHas(mask, RACE_MASK[raceID]) -- unknown race: don't filter
end

local function ClassAllowed(mask, classID)
    return MaskHas(mask, classID and 2 ^ (classID - 1))
end

local function AnyCompleted(list)
    for _, questID in ipairs(list) do
        if IsQuestCompleted(questID) then return true end
    end
    return false
end

local function AllCompleted(list)
    for _, questID in ipairs(list) do
        if not IsQuestCompleted(questID) then return false end
    end
    return true
end

-- Re-reads which of our quests are in the log. Returns true when that set changed:
-- QUEST_LOG_UPDATE fires constantly (objective progress, opening the log, ...).
-- Asks per quest instead of walking the log: the log's entries only list what is shown,
-- so quests under a collapsed header would look as if they weren't in the log at all.
local function UpdateQuestLog()
    local changed = false
    for questID in pairs(ns.Quests) do
        local inLog = C_QuestLog.IsOnQuest(questID) or nil
        if questsInLog[questID] ~= inLog then
            questsInLog[questID] = inLog
            changed = true
        end
    end
    return changed
end

-- Remembers how many of each quest starter item the player has (bags, and bags +
-- bank). Returns true when any count changed: BAG_UPDATE_DELAYED fires on every
-- loot, sale or bag move, but only these items matter here.
local itemCounts = {} -- [itemID] = bags * 1000000 + (bags + bank)
local function UpdateItemCounts()
    local changed = false
    for itemID in pairs(ns.Items) do
        local count = GetItemCount(itemID) * 1000000 + GetItemCount(itemID, true)
        if itemCounts[itemID] ~= count then
            itemCounts[itemID] = count
            changed = true
        end
    end
    return changed
end

-------------------------------------------------------------------------------
-- Quest availability
-------------------------------------------------------------------------------

-- Returns nil when the player can't do the quest, otherwise a short status note
-- (empty string = can be started right now). The second return value explains
-- why the quest is unavailable; with explain set it includes the race/class
-- details (only /qd target needs them, so the hot paths don't build the strings).
-- ignoreProgress skips the completed / in quest log checks.
function ns.GetQuestStatus(questID, ignoreProgress, explain)
    local quest = ns.Quests[questID]
    if not quest then return nil, "quest not in data" end
    local _, reqLevel, _, races, classes, preSingle, preGroup, exclusiveTo, repeatable = unpack(quest)

    if not ignoreProgress then
        if not repeatable and IsQuestCompleted(questID) then return nil, "quest already completed" end
        if questsInLog[questID] then return nil, "quest is in your quest log" end
    end
    if not RaceAllowed(races, playerRace) then
        if not explain then return nil, "wrong race" end
        return nil, "wrong race (your raceID " .. tostring(playerRace) .. ", quest race mask " .. format("%.0f", races) .. ")"
    end
    if not ClassAllowed(classes, playerClass) then
        if not explain then return nil, "wrong class" end
        return nil, "wrong class (your classID " .. tostring(playerClass) .. ", quest class mask " .. classes .. ")"
    end
    if AnyCompleted(exclusiveTo) then return nil, "exclusive quest already completed" end

    if #preSingle > 0 and not AnyCompleted(preSingle) then
        return "|cff808080(needs previous quest)|r"
    end
    if #preGroup > 0 and not AllCompleted(preGroup) then
        return "|cff808080(needs previous quests)|r"
    end
    if reqLevel and reqLevel > playerLevel then
        return "|cffff4040(level " .. reqLevel .. ")|r"
    end
    return ""
end

-- Like GetQuestStatus, but also hides rare drops and items the player already has
-- (/qd target passes explain to get the detailed reason for hidden drops).
function ns.GetDropStatus(itemID, questID, chance, explain)
    if not ns.Quests[questID] then return nil, "quest not in data" end
    if ns.db.showAll then return "" end

    if chance and chance < ns.RARE_CHANCE and not ns.db.showRare then
        if not explain then return nil, "rare drop" end
        return nil, "rare drop (below " .. ns.RARE_CHANCE .. "%, /qd rare to show)"
    end
    if GetItemCount(itemID, true) > 0 then return nil, "item already in bags/bank" end
    return ns.GetQuestStatus(questID, false, explain)
end

-- Cached GetDropStatus for a drop entry; the cache is wiped by ns.Refresh().
function ns.GetCachedStatus(drop)
    local status = statusCache[drop]
    if status == nil then
        status = ns.GetDropStatus(drop[1], drop[2], drop[3]) or false
        statusCache[drop] = status
    end
    return status
end

-- Returns a list of {itemID, questID, chance, status} for the given NPC, or nil.
-- Cached until the next refresh: tooltips ask for the same NPC many times a second.
function ns.GetAvailableDrops(npcID)
    local drops = npcID and ns.Drops[npcID]
    if not drops then return end
    local result = availableCache[npcID]
    if result ~= nil then return result or nil end
    for _, drop in ipairs(drops) do
        local status = ns.GetCachedStatus(drop)
        if status then
            result = result or {}
            result[#result + 1] = { drop[1], drop[2], drop[3], status }
        end
    end
    availableCache[npcID] = result or false
    return result
end

-- Returns the itemID of the first available drop for the given NPC, or nil.
function ns.GetFirstAvailableItem(npcID)
    local drops = npcID and ns.Drops[npcID]
    if not drops then return end
    for _, drop in ipairs(drops) do
        if ns.GetCachedStatus(drop) then
            return drop[1]
        end
    end
end

-------------------------------------------------------------------------------
-- Formatting
-------------------------------------------------------------------------------

-- Average number of kills until the first drop (1 / p for a p% chance per kill).
local function FormatKills(chance)
    local kills = max(1, floor(100 / chance + 0.5))
    local text = BreakUpLargeNumbers and BreakUpLargeNumbers(kills) or tostring(kills)
    return " |cff808080(~" .. text .. (kills == 1 and " kill)|r" or " kills)|r")
end

function ns.FormatChance(chance)
    if not chance then return "|cff808080drop chance unknown|r" end
    local text
    if chance < 0.01 then
        text = "|cffffffff<0.01% drop|r"
    elseif chance < 1 then
        text = format("|cffffffff%.2f%% drop|r", chance)
    else
        text = format("|cffffffff%.1f%% drop|r", chance)
    end
    return text .. FormatKills(chance)
end

local GetItemIconByID = (C_Item and C_Item.GetItemIconByID) or GetItemIcon

function ns.GetIcon(itemID)
    return GetItemIconByID(itemID) or QUEST_ICON
end

-- Items whose info the client is still loading; GET_ITEM_INFO_RECEIVED redraws them.
local pendingItems = {}
local RequestLoadItem = C_Item and C_Item.RequestLoadItemDataByID

function ns.GetItemName(itemID)
    local name, _, quality = GetItemInfo(itemID)
    if name then
        local color = ITEM_QUALITY_COLORS[quality]
        return (color and color.hex or "|cffffffff") .. name .. "|r"
    end
    -- Not in the client cache yet: plain name from our data for now. GetItemInfo
    -- already asked the server; RequestLoadItemDataByID makes sure of it.
    if not pendingItems[itemID] then
        pendingItems[itemID] = true
        if RequestLoadItem then RequestLoadItem(itemID) end
    end
    return "|cffffffff" .. (ns.Items[itemID] or ("Item " .. itemID)) .. "|r"
end

-- Returns the item part (icon + name) and the quest part ("starts: ..." + status).
function ns.FormatDropParts(drop)
    local itemID, questID, status = drop[1], drop[2], drop[4]
    local item = "|T" .. ns.GetIcon(itemID) .. ":0|t " .. ns.GetItemName(itemID)
    local quest = "    |cffffd100starts: " .. ns.Quests[questID][1] .. "|r"
    if status ~= "" then
        quest = quest .. " " .. status
    end
    return item, quest
end

-- Single line version for chat output.
function ns.FormatDrop(drop)
    local item, quest = ns.FormatDropParts(drop)
    return item .. " (" .. ns.FormatChance(drop[3]) .. ")" .. quest
end

-------------------------------------------------------------------------------
-- Module hooks and refresh
-------------------------------------------------------------------------------

local loginHandlers, refreshHandlers, eventHandlers = {}, {}, {}
local eventFrame = CreateFrame("Frame")

-- Module handlers run isolated: an error in one module must not stop the others
-- (e.g. a nameplate error keeping the minimap button from updating). Each distinct
-- error is printed once, since the game hides Lua errors by default.
local reportedErrors = {}
local function ReportError(err)
    err = tostring(err)
    if not reportedErrors[err] then
        reportedErrors[err] = true
        print(ns.PREFIX .. "|cffff4040error:|r " .. err)
    end
    local handler = geterrorhandler and geterrorhandler()
    if handler then handler(err) end
end

-- xpcall in Lua 5.1 takes no arguments for the function. Passing them through
-- upvalues instead of a closure keeps this allocation-free: it runs on every event.
-- (Nested calls are safe: Run reads the upvalues before calling the handler.)
local runFn, runA, runB, runC, runD
local function Run()
    return runFn(runA, runB, runC, runD)
end

local function SafeCall(fn, a, b, c, d)
    runFn, runA, runB, runC, runD = fn, a, b, c, d
    xpcall(Run, ReportError)
end

-- fn() runs once at PLAYER_LOGIN, in file load order, after the core is set up.
function ns.OnLogin(fn)
    loginHandlers[#loginHandlers + 1] = fn
end

-- fn() runs on every refresh, after cached drop statuses were dropped.
function ns.OnRefresh(fn)
    refreshHandlers[#refreshHandlers + 1] = fn
end

-- fn(...) receives the event arguments. Call from an ns.OnLogin handler.
function ns.RegisterEvent(event, fn)
    if not eventHandlers[event] then
        eventHandlers[event] = {}
        eventFrame:RegisterEvent(event)
    end
    table.insert(eventHandlers[event], fn)
end

local settingHandlers = {}

-- fn(value) runs right when the setting changes through ns.SetOption.
function ns.OnSettingChanged(key, fn)
    settingHandlers[key] = settingHandlers[key] or {}
    table.insert(settingHandlers[key], fn)
end

-- Changes a saved setting, applies it immediately and refreshes everything.
function ns.SetOption(key, value)
    ns.db[key] = value
    for _, fn in ipairs(settingHandlers[key] or {}) do SafeCall(fn, value) end
    ns.Refresh()
end

-- Drops cached state and lets every module update (nameplates, reminders, browser...).
function ns.Refresh()
    wipe(statusCache)
    wipe(availableCache)
    for _, fn in ipairs(refreshHandlers) do SafeCall(fn) end
end

-- Coalesces bursts of events into one refresh, and skips it when nothing that
-- matters changed. kind: nil = always refresh; "questlog" = only if the quests in
-- the log changed; "bags" = only if the count of a quest starter item changed.
local refreshPending = false
local pendingFull, pendingQuestLog, pendingBags = false, false, false

local function RunScheduledRefresh()
    refreshPending = false
    local changed = pendingFull
    if pendingQuestLog and UpdateQuestLog() then changed = true end
    if pendingBags and UpdateItemCounts() then changed = true end
    pendingFull, pendingQuestLog, pendingBags = false, false, false
    if changed then ns.Refresh() end
end

function ns.ScheduleRefresh(kind)
    if kind == "questlog" then
        pendingQuestLog = true
    elseif kind == "bags" then
        pendingBags = true
    else
        pendingFull = true
    end
    if refreshPending then return end
    refreshPending = true
    C_Timer.After(0.5, RunScheduledRefresh)
end

-- fn() runs shortly after the client loaded item info that ns.GetItemName had to
-- fall back on, so names can be redrawn with their quality colour.
local itemInfoHandlers = {}
function ns.OnItemInfoLoaded(fn)
    itemInfoHandlers[#itemInfoHandlers + 1] = fn
end

local itemInfoPending = false
local function RunItemInfoHandlers()
    itemInfoPending = false
    for _, fn in ipairs(itemInfoHandlers) do SafeCall(fn) end
end

local function OnItemInfoReceived(itemID, success)
    if not pendingItems[itemID] then return end -- fires for every item in the game
    -- A failed load stays pending: redrawing would only ask for the item again, forever.
    if not success then return end
    pendingItems[itemID] = nil
    if itemInfoPending then return end
    itemInfoPending = true
    C_Timer.After(0.2, RunItemInfoHandlers) -- items often arrive in bursts
end

-------------------------------------------------------------------------------
-- Events
-------------------------------------------------------------------------------

local function OnPlayerLogin()
    playerRace = select(3, UnitRace("player"))
    playerClass = select(3, UnitClass("player"))
    playerLevel = UnitLevel("player")
    UpdateQuestLog()
    UpdateItemCounts()

    ns.RegisterEvent("QUEST_LOG_UPDATE", function() ns.ScheduleRefresh("questlog") end)
    ns.RegisterEvent("QUEST_TURNED_IN", function()
        ns.ScheduleRefresh("questlog")
        ns.ScheduleRefresh() -- the quest is now completed, even if the log looks the same
    end)
    ns.RegisterEvent("BAG_UPDATE_DELAYED", function() ns.ScheduleRefresh("bags") end)
    ns.RegisterEvent("PLAYER_LEVEL_UP", function(level)
        playerLevel = level -- UnitLevel() is not updated yet at this point
        ns.ScheduleRefresh()
    end)
    ns.RegisterEvent("GET_ITEM_INFO_RECEIVED", OnItemInfoReceived)

    for _, fn in ipairs(loginHandlers) do SafeCall(fn) end
end

eventFrame:RegisterEvent("ADDON_LOADED")
eventFrame:RegisterEvent("PLAYER_LOGIN")
eventFrame:SetScript("OnEvent", function(self, event, ...)
    if event == "ADDON_LOADED" then
        if ... ~= ADDON_NAME then return end
        WildDropsDB = WildDropsDB or {}
        ns.db = WildDropsDB
        for key, value in pairs(ns.defaults) do
            if ns.db[key] == nil then ns.db[key] = value end
        end
        self:UnregisterEvent("ADDON_LOADED")
    elseif event == "PLAYER_LOGIN" then
        OnPlayerLogin()
    elseif eventHandlers[event] then
        for _, fn in ipairs(eventHandlers[event]) do SafeCall(fn, ...) end
    end
end)
